=== filter-bar
     1	export { filterBar } from './lib/filter-bar.js';
     1	import { esc } from '#kit/utils';
     2	
     3	/**
     4	 * A GET form for a page's filters. `fields` is trusted HTML, usually
     5	 * `selectField` output; public/kit.js submits the form when a field marked
     6	 * `data-autosubmit` changes. `keep` carries query state the bar should not
     7	 * drop, such as the current sort.
     8	 *
     9	 * @param {object} opts
    10	 * @param {string} opts.action
    11	 * @param {string[]} opts.fields
    12	 * @param {Record<string, string | undefined>} [opts.keep]
    13	 * @returns {string}
    14	 */
    15	export function filterBar({ action, fields, keep = {} }) {
    16	  const hidden = Object.entries(keep)
    17	    .filter(([, v]) => v !== undefined && v !== '')
    18	    .map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`)
    19	    .join('');
    20	  return `<form class="kit-filter-bar" method="get" action="${esc(action)}">${fields.join('')}${hidden}</form>`;
    21	}
=== select
     1	export { selectField } from './lib/select.js';
     1	import { esc } from '#kit/utils';
     2	
     3	/**
     4	 * Labeled select. Inside a `filterBar`, changing it submits the bar's form.
     5	 *
     6	 * @param {object} opts
     7	 * @param {string} opts.name Query parameter name.
     8	 * @param {string} opts.label
     9	 * @param {Array<{value: string, label: string}>} opts.options
    10	 * @param {string} [opts.value] The selected value.
    11	 * @returns {string}
    12	 */
    13	export function selectField({ name, label, options, value }) {
    14	  const items = options
    15	    .map((o) => {
    16	      const selected = o.value === value ? ' selected' : '';
    17	      return `<option value="${esc(o.value)}"${selected}>${esc(o.label)}</option>`;
    18	    })
    19	    .join('');
    20	  return `<label class="kit-field"><span class="kit-field__label">${esc(label)}</span><select name="${esc(name)}" class="kit-select" data-autosubmit>${items}</select></label>`;
    21	}
