     1	export { emptyState } from './lib/empty.js';
     1	import { esc } from '#kit/utils';
     2	
     3	/**
     4	 * Placeholder for a list or panel with nothing to show.
     5	 *
     6	 * @param {{title: string, body?: string}} opts `body` is trusted HTML.
     7	 * @returns {string}
     8	 */
     9	export function emptyState({ title, body = '' }) {
    10	  const more = body ? `<div class="kit-empty__body">${body}</div>` : '';
    11	  return `<div class="kit-empty"><p class="kit-empty__title">${esc(title)}</p>${more}</div>`;
    12	}
=== utils
     1	export { attrs, cx, esc } from './lib/utils.js';
     1	// Escapes text for HTML element content and quoted attribute values.
     2	export function esc(value) {
     3	  return String(value ?? '')
     4	    .replaceAll('&', '&amp;')
     5	    .replaceAll('<', '&lt;')
     6	    .replaceAll('>', '&gt;')
     7	    .replaceAll('"', '&quot;')
     8	    .replaceAll("'", '&#39;');
     9	}
    10	
    11	// Joins class names, skipping falsy ones.
    12	export function cx(...names) {
    13	  return names.filter(Boolean).join(' ');
    14	}
    15	
    16	// Renders an attribute map as ` name="value"` pairs. true renders the bare
    17	// attribute; false, null and undefined are left out.
    18	export function attrs(map = {}) {
    19	  return Object.entries(map)
    20	    .filter(([, v]) => v !== false && v !== null && v !== undefined)
    21	    .map(([k, v]) => (v === true ? ` ${esc(k)}` : ` ${esc(k)}="${esc(v)}"`))
    22	    .join('');
    23	}

